 229   // Abstract-first CSR write with Program Buffer fallback.
 230   // Tries an abstract register write; if the DM signals cmderr, clears it,
 231   // stages the value in scratch_gpr via abstract GPR write, then executes a
 232   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
 233   // to x5 (t0) which the GPR restore loop overwrites later.
 234   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
 235                                  uint8_t scratch_gpr = 5)
 236   {
 237     write_64bit_register(regno_csr(csr), value);
 238     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
 239     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
 240     write_64bit_register(regno_gpr(scratch_gpr), value);
 241     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
 242     exec_progbuf(bus_, std::span<const uint32_t>{pb});
 243   }
