 256   // is rejected until the bits are W1C-cleared. We tolerate per-register
 257   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
 258   // error before resuming so the hart isn't left in a stuck state.
 259   // B17: record the last observed non-zero cmderr and a clear count so a
 260   // partially-broken restore is observable via the public accessors
 261   // instead of silently swallowed.
 262   void clear_cmderr_if_set()
 263   {
 264     const auto status = bus_.read(kAbstractcs);
 265     const auto code = (status & kAbstractcsCmderrMask) >> 8;
 266     if (code != 0u) {
 267       last_observed_cmderr_ = code;
 268       ++cmderr_clear_count_;
