 286 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
 287 // via an Abstract Command. Halts-and-reads contract: caller must have the
 288 // hart in the halted state. Shared with StateDrain (drain at exit). If
 289 // abstractcs.cmderr goes sticky after the command, the helper clears it and
 290 // reports nullopt rather than blocking the caller -- a missing CSR mirrors as
 291 // absent instead of corrupting the adjacent field.
 292 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
 293                                      const char* poll_label
 294                                        = "read_register_64")
 295   -> std::optional<uint64_t>
 296 {
 297   using RD = ResumeDriver;
 298   bus.write(RD::kCommand,
 299             access_register_command(regno, AarSize::Bits64, /*write=*/false));
 300   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
 301   const auto status = bus.read(RD::kAbstractcs);
 302   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
 303     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
 304     return std::nullopt;
 305   }
 306   const uint64_t lo = bus.read(RD::kData0);
 307   const uint64_t hi = bus.read(RD::kData1);
 308   return lo | (hi << 32);
 309 }
 310 
 311 inline auto read_register_64(DmiBus& bus, uint16_t regno,
 312                              const char* poll_label = "read_register_64")
 313   -> uint64_t
 314 {
 315   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
 316 }
